let text = items[0].json.body;

// Remove markdown-style links: [visible text](url)
text = text.replace(/[([^]]+)]([^)]+)/g, '$1');

// Remove raw http/https URLs
text = text.replace(/https?://S+/g, '');

// Remove stray square brackets
text = text.replace(/[[]]/g, '');

return [{ json: { cleanText: text } }];

// n8n Code Node (Run Once for All Items)

const order = ["facebook_page", "instagram", "linkedin", "twitter"];

// Collect all incoming items into a single array
const inputArray = items.map(item => item.json);

// Sort by provider order
const sorted = inputArray.sort((a, b) => {
  return order.indexOf(a.provider) - order.indexOf(b.provider);
});

// Return each item separately so n8n is happy
return sorted.map(entry => ({
  json: entry
}));

